<?php require 'db.php';require 'helpers.php';require_admin();$events=(int)$pdo->query('SELECT COUNT(*) FROM events WHERE deleted_at IS NULL')->fetchColumn();$users=(int)$pdo->query("SELECT COUNT(*) FROM users WHERE status='active'")->fetchColumn();$regs=(int)$pdo->query("SELECT COUNT(*) FROM registrations r JOIN students s ON s.id=r.student_id JOIN events e ON e.id=r.event_id WHERE s.status='active' AND e.deleted_at IS NULL")->fetchColumn();$unread=(int)$pdo->query("SELECT COUNT(*) FROM contact_messages WHERE status='unread'")->fetchColumn();$latest=$pdo->query("SELECT s.name,s.email,e.event_name,r.registered_at FROM registrations r JOIN students s ON s.id=r.student_id JOIN events e ON e.id=r.event_id WHERE s.status='active' AND e.deleted_at IS NULL ORDER BY r.registered_at DESC LIMIT 10")->fetchAll();page_header('Admin Dashboard');?><section class="hero"><span class="eyebrow">Administration workspace</span><h1>Portal overview</h1><p>Monitor student activity, keep event information organized, and review recent registrations.</p></section><div class="grid" style="margin-top:20px"><?php foreach(['Events'=>$events,'Active Users'=>$users,'Event Registrations'=>$regs,'Unread Messages'=>$unread] as $k=>$v):?><section class="stat-card"><span><?=e($k)?></span><strong><?=$v?></strong></section><?php endforeach;?></div><section class="panel"><div class="split"><h2>Latest registrations</h2><span class="pill">Live overview</span></div><table><tr><th>Student</th><th>Email</th><th>Event</th><th>Registered</th></tr><?php foreach($latest as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['email'])?></td><td><?=e($r['event_name'])?></td><td><?=e($r['registered_at'])?></td></tr><?php endforeach;?></table><p><a class="btn" href="students.php">Manage Students</a> <a class="btn" href="event_manage.php">Manage Events</a> <a class="btn" href="contact_messages.php">Contact Messages (<?=$unread?> unread)</a> <a class="btn" href="audit_logs.php">Audit Logs</a></p></section><?php page_footer();?>